CREATE OR REPLACE FUNCTION public.people_effective_settings(t uuid,v uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NOT NULL AND NOT (public.user_has_tenant(auth.uid(),t) OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Tenant access required';END IF;SELECT '{"rota":true,"clock_in":"off","pay_hours":"rota","leave_requests":true,"sick_notes":true,"staff_app":false,"payslips":false,"managers_change_pay":true,"reliability":true,"approvals":"owner_run","flag_lateness":false,"lateness_minutes":15,"flag_extra_hours":false,"extra_hours_minutes":30}'::jsonb || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id IS NULL),'{}') || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id=v),'{}') INTO result;IF result->>'pay_hours'='clock_ins' THEN result:=result||'{"pay_hours":"rota"}';END IF;IF NOT (result->>'staff_app')::boolean THEN result:=result||'{"payslips":false}';END IF;RETURN result;END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.save_people_settings(uuid,uuid,jsonb)'::regprocedure) INTO def;def:=replace(def,'''managers_change_pay'',''reliability''','''managers_change_pay'',''reliability'',''flag_lateness'',''flag_extra_hours''');def:=replace(def,'''rota'',''clock_ins'',''typed_monthly''','''rota'',''typed_monthly''');def:=replace(def,'ELSIF k=''approvals''','ELSIF k IN (''lateness_minutes'',''extra_hours_minutes'') THEN IF jsonb_typeof(p->k)<>''number'' OR (p->>k)::numeric NOT BETWEEN 1 AND 1440 OR (p->>k)::numeric<>trunc((p->>k)::numeric) THEN RAISE EXCEPTION ''Invalid minutes'';END IF; ELSIF k=''approvals''');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_preview(uuid,integer,integer)'::regprocedure) INTO def;
def:=replace(def,'IF rate IS NULL AND p.id IS NOT NULL THEN rate:=p.forecast_base_salary;END IF;','');
def:=regexp_replace(def,'ELSIF source=''clock_ins'' THEN.*?ELSE IF basis=''hour''','ELSE IF basis=''hour''','s');
def:=regexp_replace(def,'IF expected>confirmed AND source=''clock_ins'' THEN.*?IF source=''rota'' AND','IF source=''rota'' AND','s');
def:=replace(def,'total_hours:=total_hours+hours;','IF source=''rota'' AND d<=today AND EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type=''regular'') THEN expected:=expected+1;IF NOT EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type=''regular'' AND hours_confirmed_at IS NULL) THEN confirmed:=confirmed+1;END IF;END IF;total_hours:=total_hours+hours;');
def:=replace(def,'IF p.id IS NOT NULL THEN earned:=','IF p.id IS NOT NULL AND (legacy OR p.accrual_journal_entry_id IS NOT NULL OR p.salary_paid_amount>0 OR p.mpf_paid_amount>0 OR EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status=''approved'')) THEN earned:=');
def:=replace(def,'IF p.id IS NOT NULL THEN gross:=p.gross_salary;','IF p.id IS NOT NULL AND (legacy OR p.accrual_journal_entry_id IS NOT NULL OR p.salary_paid_amount>0 OR p.mpf_paid_amount>0 OR EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status=''approved'')) THEN gross:=p.gross_salary;');
def:=replace(def,'gross:=earned+COALESCE(p.actual_overtime,0)','IF NOT legacy AND p.id IS NOT NULL AND EXISTS(SELECT 1 FROM public.hr_payroll_overrides WHERE tenant_id=t AND payroll_id=p.id AND field IN (''earned_salary_override'',''forecast_allowances'')) THEN earned:=COALESCE(p.earned_salary_override,earned);END IF;gross:=earned+COALESCE(p.actual_overtime,0)');
IF def LIKE '%sum(hours_worked)%' THEN RAISE EXCEPTION 'Clock-in payroll branch remains';END IF;EXECUTE def;
SELECT pg_get_functiondef('public.payroll_prepare(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'END IF;END LOOP;','END IF; IF r->>''id'' IS NOT NULL THEN UPDATE public.hr_payroll SET earned_salary_override=(r->>''earned_salary_override'')::numeric,forecast_allowances=(r->>''forecast_allowances'')::numeric,annual_leave_pay=(r->>''annual_leave_pay'')::numeric,unpaid_leave_deduction=(r->>''unpaid_leave_deduction'')::numeric,gross_salary=(r->>''gross_salary'')::numeric,mpf_employee=(r->>''mpf_employee'')::numeric,mpf_employer=(r->>''mpf_employer'')::numeric,net_salary=(r->>''net_salary'')::numeric,mpf_payment_amount=(r->>''mpf_payment_amount'')::numeric,total_deductions=(r->>''mpf_employee'')::numeric+other_deductions,preparation=r->''preparation'' WHERE id=(r->>''id'')::uuid AND tenant_id=t AND preparation IS NOT NULL AND accrual_journal_entry_id IS NULL AND salary_paid_amount=0 AND mpf_paid_amount=0;END IF; END LOOP;');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_override(uuid,uuid,text,numeric,numeric,text,boolean,integer)'::regprocedure) INTO def;def:=replace(def,'Hours come from rota or confirmed clock-ins','Hours come from rota');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_override_batch(uuid,jsonb,boolean,integer)'::regprocedure) INTO def;def:=replace(def,'Invalid payroll proposal','Invalid pay instruction');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.rota_confirm_hours(t uuid,v uuid,d date,rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p jsonb;s public.hr_shifts;BEGIN IF NOT public.rota_manager(t,v,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean OR d>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Rota confirmation unavailable';END IF;IF jsonb_typeof(rows)<>'array' OR jsonb_array_length(rows)=0 THEN RAISE EXCEPTION 'Choose rota shifts';END IF;FOR p IN SELECT value FROM jsonb_array_elements(rows) LOOP SELECT * INTO s FROM public.hr_shifts WHERE id=(p->>'id')::uuid AND tenant_id=t AND shift_date=d AND (venue_id=v OR venue_id IS NULL AND EXISTS(SELECT 1 FROM public.hr_employees WHERE id=hr_shifts.employee_id AND tenant_id=t AND venue_id=v)) FOR UPDATE;IF s.id IS NULL OR s.updated_at IS DISTINCT FROM (p->>'updated_at')::timestamptz OR NOT public.people_person_access(t,s.employee_id,auth.uid()) THEN RAISE EXCEPTION 'Rota changed; reload before confirming';END IF;UPDATE public.hr_shifts SET hours_confirmed_by=auth.uid(),hours_confirmed_at=now() WHERE id=s.id AND tenant_id=t;END LOOP;END $$;
CREATE FUNCTION public.rota_clear_confirmation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.employee_id,NEW.shift_date,NEW.start_time,NEW.end_time,NEW.break_minutes,NEW.shift_type,NEW.venue_id) IS DISTINCT FROM (OLD.employee_id,OLD.shift_date,OLD.start_time,OLD.end_time,OLD.break_minutes,OLD.shift_type,OLD.venue_id) THEN NEW.hours_confirmed_at:=NULL;NEW.hours_confirmed_by:=NULL;END IF;RETURN NEW;END $$;
CREATE TRIGGER rota_clear_day_confirmation BEFORE UPDATE ON public.hr_shifts FOR EACH ROW EXECUTE FUNCTION public.rota_clear_confirmation();
CREATE FUNCTION public.payroll_terms_candidates(t uuid,y integer,m integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN IF NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'Payroll manager required';END IF;SELECT COALESCE(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (SELECT e.id employee_id,e.first_name||' '||e.last_name name,p.id payroll_id,p.year,p.month,p.forecast_base_salary pay_amount,CASE WHEN e.employment_type='full_time' THEN 'month' ELSE 'hour' END pay_basis,e.employment_type FROM public.hr_employees e CROSS JOIN LATERAL(SELECT saved.* FROM public.hr_payroll saved WHERE saved.tenant_id=t AND saved.employee_id=e.id ORDER BY saved.year DESC,saved.month DESC,saved.created_at DESC,saved.id DESC LIMIT 1)p WHERE e.tenant_id=t AND e.hire_date<=(make_date(y,m,1)+interval '1 month -1 day')::date AND (e.end_date IS NULL OR e.end_date>=make_date(y,m,1)) AND public.people_person_access(t,e.id,auth.uid()) AND NOT EXISTS(SELECT 1 FROM public.hr_employment_terms WHERE tenant_id=t AND employee_id=e.id AND effective_date<=make_date(y,m,1) AND values->>'pay_amount' IS NOT NULL) AND p.forecast_base_salary IS NOT NULL AND p.forecast_base_salary>=0)q;RETURN result;END $$;
CREATE FUNCTION public.payroll_fill_terms(t uuid,y integer,m integer,rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;candidate jsonb;available jsonb;ids jsonb:='[]';BEGIN IF NOT public.payroll_manager(t,auth.uid()) OR jsonb_typeof(rows)<>'array' OR jsonb_array_length(rows) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Choose saved payroll terms';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||'payroll-terms',0));available:=public.payroll_terms_candidates(t,y,m);FOR c IN SELECT value FROM jsonb_array_elements(rows) LOOP SELECT value INTO candidate FROM jsonb_array_elements(available) WHERE value->>'employee_id'=c->>'employee_id' AND value->>'payroll_id'=c->>'payroll_id';IF candidate IS NULL OR candidate->>'pay_amount' IS DISTINCT FROM c->>'pay_amount' OR candidate->>'pay_basis' IS DISTINCT FROM c->>'pay_basis' THEN RAISE EXCEPTION 'Saved payroll or terms changed; check again';END IF;IF EXISTS(SELECT 1 FROM public.hr_people_changes WHERE tenant_id=t AND employee_id=(c->>'employee_id')::uuid AND status='pending' AND values ? 'pay_amount') THEN RAISE EXCEPTION 'Pay terms already awaiting owner approval';END IF;ids:=ids||jsonb_build_array(public.confirm_people_change(t,(c->>'employee_id')::uuid,make_date(y,m,1),jsonb_build_object('pay_amount',(candidate->>'pay_amount')::numeric,'pay_basis',candidate->>'pay_basis','employment_type',candidate->>'employment_type'),'pay_change',NULL));END LOOP;RETURN ids;END $$;
REVOKE ALL ON FUNCTION public.payroll_terms_candidates(uuid,integer,integer),public.payroll_fill_terms(uuid,integer,integer,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_terms_candidates(uuid,integer,integer),public.payroll_fill_terms(uuid,integer,integer,jsonb) TO authenticated;